import{t as e}from"./jsx-runtime-lw2jiZar.js";import{t}from"./braces-B2_rnCwm.js";import{C as n,E as r,M as i,N as a,O as o,P as s,_ as c,b as l,k as u,l as d,n as f,o as p,p as m,t as h,x as g}from"./shared-DhavWP79.js";import{t as _}from"./database-LLH4Psoh.js";import{t as v}from"./search-f2spAuW6.js";var y=e(),b=`Этап 4 · Блок 15 · Реализовать операции и переключить оба интерфейса`;function x({module:e}){return(0,y.jsxs)(a,{children:[(0,y.jsx)(i,{variant:`project`,chip:e??b,title:`Поиск в SQL-базе`,intro:`Перенесём уже знакомый поиск Planner в SQL и сохраним его поведение для русского текста, кавычек и символов % и _. Обычный запуск приложения пока продолжает работать с JSON.`,tags:[{icon:(0,y.jsx)(v,{size:14}),label:`буквальная подстрока`},{icon:(0,y.jsx)(_,{size:14}),label:`SQLite instr`},{icon:(0,y.jsx)(t,{size:14}),label:`title_normalized`}]}),(0,y.jsxs)(s,{number:`00`,title:`От знакомого поиска к запросу базы`,children:[(0,y.jsx)(o,{children:`Planner уже умеет находить задачу по части заголовка. При смене способа хранения важно сохранить смысл этой операции: совпадение должно зависеть от текста задачи, а не от того, лежит ли запись в JSON или в SQLite.`}),(0,y.jsx)(u,{variant:`connected`,items:[{title:`Точка старта`,description:`Существующий search_tasks передаёт фрагмент репозиторию. JSON-вариант обрезает пробелы по краям, применяет Python lower() и ищет буквальное вхождение.`},{title:`Новый вопрос`,description:`Как выполнить то же сравнение в SQLite, если нижний регистр, шаблоны LIKE и пустой фрагмент имеют свои правила?`},{title:`Результат`,description:`Мы разберём Unicode-регистр и instr, затем добавим SQL-поиск в существующий репозиторий и сравним его с прежним договором.`}]}),(0,y.jsx)(`p`,{children:`Сначала восстановим точные правила знакомой операции. Потом проверим два отличия SQLite: встроенный lower() работает только с ASCII, а LIKE считает некоторые символы шаблонами. Когда механизм станет понятен, мы свяжем его с уже предусмотренной колонкой title_normalized и проследим путь результата через репозиторий. Так меняется реализация хранения, а вызовы сервиса остаются прежними.`})]}),(0,y.jsxs)(s,{number:`01`,title:`Сначала зафиксируем договор поиска`,children:[(0,y.jsx)(o,{children:`Прежде чем выбирать SQL-функцию, полезно отделить правила продукта от деталей текущего JSON-кода.`}),(0,y.jsx)(`p`,{children:`Сервис Planner вызывает search_tasks(query), а репозиторий отвечает списком подходящих Task. В JSON-адаптере фрагмент сначала очищается через strip(), затем приводится к нижнему регистру через Python lower(). Для каждого заголовка применяется то же преобразование, после чего проверяется включение фрагмента. Внутренние пробелы и знаки остаются частью запроса: strip() убирает только пробелы с его краёв.`}),(0,y.jsx)(`p`,{children:`Пустой после strip() фрагмент возвращает пустой список. Это важно: пустая строка является началом любой строки, и без отдельного правила она могла бы совпасть со всеми задачами. CLI дополнительно сообщает о пустом вводе до вызова сервиса. Эти две проверки решают разные задачи: интерфейс объясняет ввод, а репозиторий сохраняет корректный результат поиска независимо от вызывающего кода.`}),(0,y.jsx)(`p`,{children:`Список результатов содержит задачи, а не только заголовки. Поэтому при переносе поиска мы сохраняем прежний тип результата, внутренние tags и путь сервис → репозиторий. Новая HTTP-точка для этой операции не нужна: подтверждённый API не содержит отдельного маршрута search, а CLI уже вызывает существующий метод сервиса.`}),(0,y.jsx)(l,{question:`Что делает strip() с запросом «  отчёт за июнь  »?`,options:[`Удаляет пробелы по краям, сохраняя пробелы внутри.`,`Удаляет все пробелы из фразы.`,`Превращает пробелы в шаблон для LIKE.`],correctIndex:0,explanation:`strip() убирает только крайние пробельные символы. Фраза внутри остаётся прежней, после чего lower() меняет регистр по правилам Python.`}),(0,y.jsx)(`p`,{children:`Мы сохраняем и смысл совпадения, и границу ответственности. Сервис по-прежнему передаёт предметный запрос, репозиторий возвращает Task, а конкретный способ сравнения скрыт внутри хранения.`})]}),(0,y.jsxs)(s,{number:`02`,title:`Python lower() и SQLite lower() работают по-разному`,children:[(0,y.jsx)(o,{children:`Одинаковое имя функции ещё не означает одинаковые правила обработки текста.`}),(0,y.jsx)(`p`,{children:`Python lower() преобразует Unicode-текст по правилам Python. Встроенная SQLite lower() без расширения ICU меняет регистр только у ASCII-букв. Поэтому английское HELLO станет hello в обоих случаях, а русское слово ШЛЯПА может остаться заглавным при вызове SQLite lower(). Если поиск заменить на условие lower(title) = lower(query), поведение для кириллицы незаметно изменится.`}),(0,y.jsx)(`p`,{children:`Это похоже на двух каталогизаторов с одинаковой кнопкой «маленькие буквы», но разными словарями: один знает алфавит целиком, другой обрабатывает только латиницу. Аналогия касается таблицы преобразований. Она не говорит, что Python или SQLite всегда лучше, и не меняет правила поиска сама по себе.`}),(0,y.jsx)(`p`,{children:`В нашем проекте Unicode-нормализация уже выполняется Python-кодом при подготовке заголовка. Для запроса применяется тот же lower(). Затем SQLite сравнивает два уже нормализованных значения. Мы не просим базу повторно вычислять регистр и не вводим casefold(): это другая операция Python, которая может давать другой результат и потребовала бы отдельного договора.`}),(0,y.jsx)(l,{question:`Какой вывод следует для встроенной SQLite lower() на строке «ШЛЯПА»?`,options:[`Кириллица автоматически станет строчной.`,`Кириллица останется заглавной без поддержки ICU.`,`Строка превратится в пустое значение.`],correctIndex:1,explanation:`Встроенная lower() обрабатывает ASCII. Для кириллицы она не заменяет Python lower(), поэтому обе стороны нашего сравнения нормализуются в Python.`}),(0,y.jsx)(c,{code:`import sqlite3

query = "ШЛЯПА"
with sqlite3.connect(":memory:") as db:
    sql_lower = db.execute(
        "SELECT lower(?)", (query,)
    ).fetchone()[0]
    position = db.execute(
        "SELECT instr(?, ?)",
        ("магазин шляпа", "шляпа"),
    ).fetchone()[0]
print(query.lower(), sql_lower, position, sep=" | ")`,output:`шляпа | ШЛЯПА | 9`,hint:`Отдельно проследим Python lower(), SQLite lower() и позицию начала фрагмента.`}),(0,y.jsx)(`p`,{children:`Получаем три значения: «шляпа» после Python lower(), «ШЛЯПА» после встроенной SQLite lower() и позицию 9 для фрагмента «шляпа» в строке «магазин шляпа». instr вернёт номер позиции с единицы, а ноль означает, что фрагмент не найден. В нашей операции регистр учитывается до запроса, а instr выполняет точное сравнение.`})]}),(0,y.jsxs)(s,{number:`03`,title:`LIKE ищет шаблон, instr ищет фрагмент`,children:[(0,y.jsx)(o,{children:`Теперь сравним две SQL-операции, которые внешне могут выглядеть как поиск подстроки, но трактуют ввод по-разному.`}),(0,y.jsx)(`p`,{children:`LIKE сопоставляет строку с шаблоном. Знак % в шаблоне означает любую последовательность символов, а подчёркивание _ означает один символ. Если обернуть пользовательский фрагмент знаками процента и передать в LIKE, сами проценты и подчёркивания внутри фрагмента тоже станут управляющими знаками. В результате запрос «план_%» может найти больше строк, чем буквальное вхождение именно «план_%».`}),(0,y.jsx)(`p`,{children:`Здесь важно разделить две независимые гарантии. SQLAlchemy связывает значение параметром, поэтому кавычка или другой ввод не превращаются в часть исполняемого SQL. Но параметризация не отменяет правил LIKE: переданный шаблон всё равно понимает % и _. Безопасно передать шаблон не значит искать все его символы буквально.`}),(0,y.jsx)(`p`,{children:`SQLite instr(строка, фрагмент) сообщает позицию первого буквального вхождения либо ноль. Это похоже на поиск слова в печатной строке по линейке: символы сверяются как есть, без команд шаблона. Граница аналогии в том, что SQL-функция работает над значениями строк в запросе и не является полнотекстовым индексом или ранжированным поиском.`}),(0,y.jsx)(`p`,{children:`Пустой фрагмент нужно отсечь до SQL. Для instr пустая строка находится в позиции 1, поэтому условие «позиция больше нуля» иначе пропустило бы каждую запись. Сначала применяем прежний strip(), возвращаем пустой список при отсутствии текста и только после этого строим запрос.`}),(0,y.jsx)(`p`,{children:`В следующем учебном фрагменте мы смотрим на условную таблицу заметок. Поле normalized_text и введённый fragment уже подготовлены Python lower(); так мы изолируем именно различие LIKE и буквального поиска.`}),(0,y.jsx)(n,{code:`fragment = "100% хлопок".strip().lower()
statement = select(NoticeRow).where(
    NoticeRow.normalized_text.like(
        f"%{fragment}%"
    )
)`,question:`Какой договор нарушает этот фрагмент учебного каталога?`,options:[`Знаки % внутри фрагмента становятся wildcard-шаблоном LIKE.`,`SQLAlchemy передаёт строку только как часть имени столбца.`,`Параметр LIKE автоматически вызывает Python lower().`],correctIndex:0,explanation:`SQLAlchemy связывает выражение как значение, поэтому проблема не в кавычках или исполнении кода. Но знак % внутри шаблона остаётся специальным символом LIKE, и поиск перестаёт быть буквальным.`,fix:`from sqlalchemy import func, select

fragment = "100% хлопок".strip().lower()
statement = select(NoticeRow).where(
    func.instr(
        NoticeRow.normalized_text, fragment
    ) > 0
)`}),(0,y.jsx)(`p`,{children:`В исправленном независимом примере fragment остаётся параметром, а instr проверяет последовательность буквально. В проектной операции к этому сравнению добавятся существующий mapping в Task и явный порядок результата. Пустое значение всё равно обрабатывается отдельно, прежде чем функция попадёт в условие.`})]}),(0,y.jsxs)(s,{number:`04`,title:`title_normalized должен обновляться вместе с title`,children:[(0,y.jsx)(o,{children:`Сравнивать через instr можно только тогда, когда в колонке лежит значение, нормализованное тем же способом, что и запрос.`}),(0,y.jsx)(`p`,{children:`В исходной схеме рядом с title уже предусмотрен технический title_normalized. При создании строки туда записывается title.lower(), вычисленный Python. Тогда для запроса «ШАПКА» мы ищем «шапка» в таком же заранее подготовленном заголовке. Это сохраняет прежнее поведение кириллического регистра без дополнительного SQL lower(). Колонка не входит в предметную Task или HTTP-ответ.`}),(0,y.jsx)(`p`,{children:`Представим карточку в бумажном каталоге: исходный заголовок остаётся на основной стороне, а на боковой вкладке лежит согласованная поисковая форма. Мы быстро находим нужные карточки по этой форме, но источник названия остаётся исходным. Граница сравнения важна: вкладка не является отдельной копией с собственной логикой, и она бесполезна, если её забывают поправить после переименования.`}),(0,y.jsx)(`p`,{children:`Поэтому все пути записи поддерживают пару title/title_normalized согласованно. Создание готовит оба значения; PUT и PATCH меняют нормализованное значение только вместе с title; импорт вычисляет его для старых задач тем же Python lower(). При поиске мы лишь читаем готовую колонку. Обновлять каждую строку из search или добавлять колонку в уже созданную таблицу не нужно.`}),(0,y.jsx)(`p`,{children:`Практическая проверка должна поймать рассогласование. Если задачу переименовали, поиск по старому фрагменту перестаёт её находить, а поиск по новому начинает. При импорте сохраняются прежние id и tags, а техническое поле не появляется в публичной схеме. Одинаковые заголовки допустимы: совпадение возвращает каждую отдельную задачу.`}),(0,y.jsx)(m,{prompt:`Сопоставим каждый элемент с его ролью в поиске.`,leftTitle:`Элемент`,rightTitle:`Роль`,pairs:[{left:(0,y.jsx)(`code`,{children:`query.strip().lower()`}),right:`Готовит фрагмент по прежним правилам Python`},{left:(0,y.jsx)(`code`,{children:`title_normalized`}),right:`Хранит заголовок после Python lower()`},{left:(0,y.jsx)(`code`,{children:`instr`}),right:`Возвращает позицию буквального вхождения или ноль`},{left:`Пустой фрагмент`,right:`Даёт пустой список до SQL-запроса`}],explanation:`Одинаковое преобразование запроса и сохранённого заголовка решает вопрос регистра. instr отвечает только за буквальное вхождение, а ранняя проверка пустой строки сохраняет прежний результат.`}),(0,y.jsx)(`p`,{children:`Мы отделяем исходное название, внутреннюю поисковую форму и операцию сравнения. Каждая часть имеет одного владельца: данные готовятся путями записи, ввод нормализуется сервисной логикой, а SQL-репозиторий находит подходящие строки.`})]}),(0,y.jsxs)(s,{number:`05`,title:`SQL-поиск остаётся внутри репозитория`,children:[(0,y.jsx)(o,{children:`Последний шаг связывает знакомый метод сервиса с запросом и обычными предметными объектами.`}),(0,y.jsx)(`p`,{children:`В SQLAlchemy func.instr выражает вызов встроенной функции базы в дереве SQL-запроса. Python не запускает её для каждой Task: Session отправляет сформированное выражение SQLite, где WHERE оставляет только совпавшие строки. Сам фрагмент передаётся значением условия, а не склеивается с текстом SQL.`}),(0,y.jsx)(`p`,{children:`Чтобы поведение было понятным и повторяемым, запрос явно задаёт order_by по id. В обычной истории Planner это соответствует последовательности создания задач, которую мы привыкли видеть в файловой версии. Произвольная ручная перестановка строк в старом JSON не становится дополнительным контрактом порядка для SQL: таблица без отдельного поля позиции такой порядок не хранит.`}),(0,y.jsx)(h,{caption:`Путь фрагмента к найденным задачам`,orientation:`vertical`,children:(0,y.jsxs)(p,{label:`Преобразование запроса, SQL-фильтр и mapping результата`,orientation:`vertical`,className:`lesson-json-snapshot-flow`,children:[(0,y.jsx)(d,{title:`Фрагмент в Python`,children:(0,y.jsx)(`p`,{children:`strip() и lower()`})}),(0,y.jsx)(f,{label:`передаёт значение`}),(0,y.jsx)(d,{title:`Условие SQLite`,children:(0,y.jsx)(`p`,{children:`instr по title_normalized`})}),(0,y.jsx)(f,{label:`отбирает строки`}),(0,y.jsx)(d,{title:`Совпавшие TaskRow`,children:(0,y.jsx)(`p`,{children:`порядок по id`})}),(0,y.jsx)(f,{label:`task_from_row`}),(0,y.jsx)(d,{title:`Результат Planner`,shape:`process`,children:(0,y.jsx)(`p`,{children:`обычный список Task`})})]})}),(0,y.jsx)(`p`,{children:`На схеме читаем сверху вниз. Python приводит только введённый фрагмент к прежнему виду и передаёт его SQL как значение. SQLite фильтрует строки по уже подготовленному title_normalized, а mapping превращает найденные ORM-строки в обычные Task до завершения Session. На узком экране порядок чтения остаётся тем же.`}),(0,y.jsx)(`p`,{children:`SqlTaskRepository.search реализует уже существующий договор хранения и возвращает Task. Сервис и обработчик CLI продолжают вызывать знакомый метод. Проверка handle_search с SQL-сервисом проходит в отдельной ресурсной области, она не меняет главный цикл run. Репозиторий не закрывает Session и не подтверждает транзакцию чтения, а HTTP не получает новый маршрут или поле title_normalized. Пока не завершено общее переключение, обычные API и CLI продолжают использовать JSON.`}),(0,y.jsxs)(r,{tone:`info`,children:[`SQLite документирует instr() как поиск первого вхождения строки и lower() как преобразование ASCII-букв. Основное правило уже разобрано здесь; `,(0,y.jsx)(`a`,{href:`https://www.sqlite.org/lang_corefunc.html`,target:`_blank`,rel:`noreferrer`,children:`справка по встроенным функциям SQLite`}),` пригодится для сверки сигнатур.`]}),(0,y.jsx)(g,{question:`Почему поиск не должен вызывать list(), а затем фильтровать Task в Python?`,hint:`Вспомним, какая часть запроса уже умеет отбирать строки до их передачи приложению.`,answer:(0,y.jsx)(`p`,{children:`Такой обход загружает все строки и делает фильтрацию после чтения. Репозиторий выражает условие через SQL, получает только совпавшие TaskRow, задаёт порядок по id и преобразует результат в Task. Объём передачи и работа соответствуют предметному запросу.`})})]}),(0,y.jsxs)(s,{number:`06`,title:`Что мы будем делать в практике`,children:[(0,y.jsx)(o,{children:`Мы добавим один SQL-метод к существующей границе хранения и докажем, что знакомые входы дают ожидаемые совпадения.`}),(0,y.jsx)(u,{variant:`connected`,items:[{title:`Сверим прежний договор`,description:`Проследим search_tasks и JSON-адаптер на обычном, пробельном и пустом запросе. Зафиксируем буквальный смысл фрагмента и роль CLI-проверки.`},{title:`Сравним механизмы`,description:`На небольшом независимом SQLite-примере проверим Python lower(), SQLite lower(), шаблон LIKE и буквальный instr.`},{title:`Добавим SQL-операцию`,description:`Реализуем search в app/DBase/repositories.py через параметризованное условие по title_normalized и вернём обычные Task.`},{title:`Проверим изменяемые данные`,description:`Сравним русский и латинский регистр, кавычки, %, _, пробелы, дубли заголовков и поиск после переименования или импорта. Существующий handle_search вызывается с SQL-сервисом внутри отдельной ресурсной области.`},{title:`Подтвердим границу`,description:`Убедимся, что поиск выполняет SQL, не вызывает полный list для Python-фильтра, не добавляет HTTP-маршрут и не переключает JSON-сборку.`}]}),(0,y.jsx)(`p`,{children:`Каждый шаг подготовлен пройденной теорией: первый восстанавливает договор, второй наблюдает разницу механизмов, третий соединяет их в SQL-репозитории, а последние проверяют результат после записи и импорта. Предыдущие занятия уже дают SQL create, PUT/PATCH, done/delete, выборку, статистику и отдельный импорт, поэтому здесь мы используем эти операции на тестовой базе, не реализуя их повторно.`}),(0,y.jsx)(`p`,{children:`Для прежних возможностей отдельно проверим обычный путь API и CLI через JSON, предметные Task с tags и совпадения после обновления заголовка. Это завершает перенос операции поиска, но не меняет источник штатных данных. Следующий шаг настраивает ресурс Session для каждой CLI-команды.`})]})]})}export{x as Lesson95};